import{_ as t,o as r,c as a,a3 as o}from"./chunks/framework.CDCjIvJ8.js";const u=JSON.parse('{"title":"Decision records","description":"","frontmatter":{},"headers":[],"relativePath":"reference/decisions.md","filePath":"reference/decisions.md","lastUpdated":1789296458000}'),n={name:"reference/decisions.md"};function s(i,e,d,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="decision-records" tabindex="-1">Decision records <a class="header-anchor" href="#decision-records" aria-label="Permalink to &quot;Decision records&quot;">​</a></h1><p>Decisions that are non-obvious, or that a future reader would otherwise be likely to reverse without knowing what it cost.</p><hr><h2 id="adr-001-·-grading-runs-no-model-inference" tabindex="-1">ADR-001 · Grading runs no model inference <a class="header-anchor" href="#adr-001-·-grading-runs-no-model-inference" aria-label="Permalink to &quot;ADR-001 · Grading runs no model inference&quot;">​</a></h2><p><strong>Accepted</strong></p><p><strong>Context.</strong> Every comparable tool asks an LLM to grade. It is far less work.</p><p><strong>Decision.</strong> The scorer is a rule engine. <code>app/ai/evaluation/</code> imports nothing from <code>app/ai/llm/</code>.</p><p><strong>Why.</strong> Model scores drift between runs on identical input, so a student can resubmit unchanged work and receive a different mark — which is indefensible when challenged. Models also hallucinate statutory citations, and a wrong citation in a legal-education product teaches the wrong law.</p><p><strong>Cost.</strong> Rubrics must be authored by hand for each document type, and the scorer cannot reward good drafting that the rubric did not anticipate.</p><p><strong>Accepting that cost buys</strong> a mark that is reproducible and attributable to a named rule with cited evidence. That is the product.</p><hr><h2 id="adr-002-·-retrieval-locates-evidence-rules-judge-it" tabindex="-1">ADR-002 · Retrieval locates evidence; rules judge it <a class="header-anchor" href="#adr-002-·-retrieval-locates-evidence-rules-judge-it" aria-label="Permalink to &quot;ADR-002 · Retrieval locates evidence; rules judge it&quot;">​</a></h2><p><strong>Accepted</strong></p><p><strong>Context.</strong> Grading uses vector search, which is not deterministic in the way a rule is.</p><p><strong>Decision.</strong> Retrieval answers <em>which passage corresponds to this requirement</em>. Whether it satisfies the requirement is decided by rules.</p><p><strong>Why.</strong> This keeps determinism intact. A retrieval drift changes which evidence is cited — visible and debuggable — rather than whether a clause passes, which would be a silent score change.</p><hr><h2 id="adr-003-·-roles-are-server-assigned-never-client-supplied" tabindex="-1">ADR-003 · Roles are server-assigned, never client-supplied <a class="header-anchor" href="#adr-003-·-roles-are-server-assigned-never-client-supplied" aria-label="Permalink to &quot;ADR-003 · Roles are server-assigned, never client-supplied&quot;">​</a></h2><p><strong>Accepted</strong> · supersedes the original design</p><p><strong>Context.</strong> The sign-up form offered a role dropdown, and the chosen value was sent to the server and honoured.</p><p><strong>Decision.</strong> <code>role</code> is absent from every request schema. Schemas use <code>extra=&quot;forbid&quot;</code>, so a client still sending one fails loudly. The role is read from <code>profiles</code> on every request. Faculty registration is gated by a hashed, use-limited institution code.</p><p><strong>Why.</strong> Anyone could obtain instructor privileges: reference-corpus upload, platform-wide analytics, and grade override on any submission.</p><p><strong>Note.</strong> Removing the field alone would have been insufficient. Had faculty sign-up stayed open, the same privileges would remain obtainable — just through the front door.</p><hr><h2 id="adr-004-·-tokens-are-verified-locally-not-against-supabase" tabindex="-1">ADR-004 · Tokens are verified locally, not against Supabase <a class="header-anchor" href="#adr-004-·-tokens-are-verified-locally-not-against-supabase" aria-label="Permalink to &quot;ADR-004 · Tokens are verified locally, not against Supabase&quot;">​</a></h2><p><strong>Accepted</strong> · supersedes the original design</p><p><strong>Context.</strong> <code>supabase.auth.get_user(token)</code> ran on every authenticated request.</p><p><strong>Decision.</strong> Verify the JWS locally against a cached JWKS, or the shared secret for legacy HS256.</p><p><strong>Why.</strong> The round trip added 100–300 ms to every endpoint and made Supabase Auth a hard availability dependency. <code>SUPABASE_JWT_SECRET</code> was already configured and simply unused.</p><p><strong>Consequence.</strong> Revocation is no longer instant — a token remains valid until it expires. Accepted because the access-token lifetime is short, and because account deactivation <em>is</em> checked on every request via the profile lookup.</p><hr><h2 id="adr-005-·-unauthorized-resources-return-404-not-403" tabindex="-1">ADR-005 · Unauthorized resources return 404, not 403 <a class="header-anchor" href="#adr-005-·-unauthorized-resources-return-404-not-403" aria-label="Permalink to &quot;ADR-005 · Unauthorized resources return 404, not 403&quot;">​</a></h2><p><strong>Accepted</strong></p><p><strong>Decision.</strong> Accessing a resource you do not own returns 404.</p><p><strong>Why.</strong> A 403 confirms the record exists, which turns any id-taking endpoint into an enumeration oracle. 404 is indistinguishable from a non-existent id.</p><p><strong>Cost.</strong> Marginally worse debugging — a genuine 404 and a permission failure look alike. The server log distinguishes them.</p><hr><h2 id="adr-006-·-the-outbox-stores-no-template-context" tabindex="-1">ADR-006 · The outbox stores no template context <a class="header-anchor" href="#adr-006-·-the-outbox-stores-no-template-context" aria-label="Permalink to &quot;ADR-006 · The outbox stores no template context&quot;">​</a></h2><p><strong>Accepted</strong></p><p><strong>Context.</strong> A transactional outbox normally queues the template plus its variables for a worker to render later.</p><p><strong>Decision.</strong> Invitations are rendered in-process and dispatched as a background task. The outbox records only delivery metadata.</p><p><strong>Why.</strong> The context would contain the raw invitation token, which would then sit in a database row and in backups — defeating the point of storing only its hash.</p><p><strong>Consequence.</strong> A permanently failed invitation is not replayable. This is correct: the instructor resends, minting a fresh token with a fresh expiry, rather than resurrecting an old one.</p><hr><h2 id="adr-007-·-embeddings-run-in-process" tabindex="-1">ADR-007 · Embeddings run in-process <a class="header-anchor" href="#adr-007-·-embeddings-run-in-process" aria-label="Permalink to &quot;ADR-007 · Embeddings run in-process&quot;">​</a></h2><p><strong>Accepted</strong></p><p><strong>Decision.</strong> FastEmbed ONNX (<code>BAAI/bge-small-en-v1.5</code>, 384-dim) in-process, rather than an embedding API.</p><p><strong>Why.</strong> It removes a network hop from a path that runs several times per evaluation, and no student draft text is sent to a third party for embedding — a meaningful property for an education platform.</p><p><strong>Cost.</strong> The model loads on first use, so a cold start is slow. Production therefore runs two instances.</p><hr><h2 id="adr-008-·-terraform-does-not-model-supabase-qdrant-or-neo4j" tabindex="-1">ADR-008 · Terraform does not model Supabase, Qdrant or Neo4j <a class="header-anchor" href="#adr-008-·-terraform-does-not-model-supabase-qdrant-or-neo4j" aria-label="Permalink to &quot;ADR-008 · Terraform does not model Supabase, Qdrant or Neo4j&quot;">​</a></h2><p><strong>Accepted</strong></p><p><strong>Decision.</strong> Those three are provisioned by hand; their credentials are variables.</p><p><strong>Why.</strong> No provider can create a project or cluster for any of them. A module that only pretends to manage a resource is worse than an honest gap: it implies a destroy would clean up state it would leave behind, and a plan would detect drift it cannot see.</p><p>The part that actually changes — the schema — is versioned in <code>backend/migrations/</code>.</p><hr><h2 id="adr-009-·-rate-limiting-fails-closed-in-production" tabindex="-1">ADR-009 · Rate limiting fails closed in production <a class="header-anchor" href="#adr-009-·-rate-limiting-fails-closed-in-production" aria-label="Permalink to &quot;ADR-009 · Rate limiting fails closed in production&quot;">​</a></h2><p><strong>Accepted</strong></p><p><strong>Decision.</strong> With <code>REDIS_REQUIRED</code>, an unavailable limiter rejects requests rather than allowing them. Production requires both <code>REDIS_REQUIRED</code> and <code>RATE_LIMIT_ENABLED</code>, validated at startup.</p><p><strong>Why.</strong> Failing open means a Redis blip silently removes every limit — including the ones bounding inference spend. A brief 429 is preferable to an unbounded bill and unthrottled credential stuffing.</p><p><strong>Note.</strong> The startup check originally required <code>REDIS_REQUIRED</code> only <em>while</em> rate limiting was enabled, so <code>RATE_LIMIT_ENABLED=False</code> passed validation and removed limits entirely. Writing the test for it surfaced that gap.</p><hr><h2 id="adr-010-·-class-membership-scopes-analytics-and-leaderboards" tabindex="-1">ADR-010 · Class membership scopes analytics and leaderboards <a class="header-anchor" href="#adr-010-·-class-membership-scopes-analytics-and-leaderboards" aria-label="Permalink to &quot;ADR-010 · Class membership scopes analytics and leaderboards&quot;">​</a></h2><p><strong>Accepted</strong> · supersedes the original design</p><p><strong>Context.</strong> Both aggregated every student in the database.</p><p><strong>Decision.</strong> Scoped through <code>class_enrollments</code> — classmates for a student, the classes they run for an instructor.</p><p><strong>Why.</strong> Every student saw the names and mean scores of every other student on the platform, across institutions. This is why the class model is a security fix and not only a feature.</p>',67)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
